package com.foodbridge.orders;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="purchase_orders",indexes=@Index(name="idx_order_consumer",columnList="consumerEmail")) public class PurchaseOrder {
    @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private Long listingId;@Column(nullable=false) private String productName;@Column(nullable=false) private String consumerEmail;@Column(nullable=false) private int quantity;@Column(nullable=false,precision=10,scale=2) private BigDecimal totalAmount;@Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status;@Column(unique=true) private String pickupCode;@Column(nullable=false) private LocalDateTime createdAt;private LocalDateTime updatedAt;
    protected PurchaseOrder(){}public PurchaseOrder(Long listingId,String productName,String email,int quantity,BigDecimal total){this.listingId=listingId;this.productName=productName;this.consumerEmail=email;this.quantity=quantity;this.totalAmount=total;this.status=OrderStatus.PENDING_PAYMENT;this.createdAt=LocalDateTime.now();this.updatedAt=createdAt;}
    public Long getId(){return id;}public Long getListingId(){return listingId;}public String getProductName(){return productName;}public String getConsumerEmail(){return consumerEmail;}public int getQuantity(){return quantity;}public BigDecimal getTotalAmount(){return totalAmount;}public OrderStatus getStatus(){return status;}public String getPickupCode(){return pickupCode;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getUpdatedAt(){return updatedAt;}public void setStatus(OrderStatus s){status=s;updatedAt=LocalDateTime.now();}public void setPickupCode(String c){pickupCode=c;updatedAt=LocalDateTime.now();}
}

